const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};

const update = $input.first().json;
const now = Date.now();
const TTL_MS = 5 * 60 * 1000;

for (const cid in data.pending) {
  if (data.pending[cid].expiresAt < now) delete data.pending[cid];
}

let chatId, text = '', callbackData, callbackId;

if (update.message) {
  chatId = update.message.chat?.id;
  text = (update.message.text || '').trim();
} else if (update.callback_query) {
  chatId = update.callback_query.message?.chat?.id;
  callbackData = update.callback_query.data;
  callbackId = update.callback_query.id;
} else {
  return [];
}

if (!chatId) return [];

const KNOWN_CALLBACKS = new Set(['cancel', 'skip', 'auto', 'post', 'retry']);
if (callbackData && !KNOWN_CALLBACKS.has(callbackData)) return [];

const pending = data.pending[chatId];

const out = (action, extra = {}) => [{
  json: { action, chatId, callbackId: callbackId || null, ...extra }
}];

if (text === '/cancel' || callbackData === 'cancel') {
  if (pending) delete data.pending[chatId];
  return out('reply_only', { text: 'cancelled; pending state cleared' });
}

if (text === '/start' || text === '/help') {
  return out('reply_only', {
    text: 'MangaBrainRot bot\n\nInput: a manga title (e.g. "one piece" or "quintessential quintuplets"). Optionally append a chapter number (e.g. "bleach 686"); otherwise the latest chapter is used.\nFlow: manganow resolve -> (auto thumb / skip) -> dispatch WF-B -> IG reel.\n\n/cancel - abort flow (5min TTL otherwise)'
  });
}

if (callbackData) {
  if (!pending) {
    return out('reply_only', { text: 'session expired (5min TTL); resend the manga title' });
  }

  if (pending.step === 'awaiting_choice' && callbackData === 'skip') {
    const dispatched = { ...pending };
    delete data.pending[chatId];
    return out('dispatch_wfb', {
      mangaId: dispatched.mangaId,
      chapterId: dispatched.chapterId,
      title: dispatched.title,
      chapterNum: dispatched.chapterNum,
      thumbUrl: '',
      prompt: '',
      ackText: 'dispatch WF-B mKfSwealmkYbbWwj\nmangaId: `' + dispatched.mangaId + '`\nchapterId: `' + dispatched.chapterId + '`\nthumbUrl: (none)'
    });
  }

  if (pending.step === 'awaiting_choice' && callbackData === 'auto') {
    pending.name = pending.title;
    pending.expiresAt = now + TTL_MS;
    return out('generate_thumbnail', { title: pending.title, chapterNum: pending.chapterNum });
  }

  if (pending.step === 'awaiting_confirm' && callbackData === 'post') {
    const dispatched = { ...pending };
    delete data.pending[chatId];
    return out('dispatch_wfb', {
      mangaId: dispatched.mangaId,
      chapterId: dispatched.chapterId,
      title: dispatched.title,
      chapterNum: dispatched.chapterNum,
      thumbUrl: dispatched.thumbUrl,
      prompt: dispatched.prompt,
      ackText: 'dispatch WF-B mKfSwealmkYbbWwj\nmangaId: `' + dispatched.mangaId + '`\nchapterId: `' + dispatched.chapterId + '`\nthumbUrl: `' + dispatched.thumbUrl + '`'
    });
  }

  if (pending.step === 'awaiting_confirm' && callbackData === 'retry') {
    pending.step = 'awaiting_choice';
    pending.expiresAt = now + TTL_MS;
    return out('generate_thumbnail', { title: pending.title, chapterNum: pending.chapterNum });
  }

  return out('reply_only', { text: 'unknown callback for current state (' + pending.step + '); /cancel to reset' });
}

if (text) {
  let title = text;
  let chapter = null;
  const m = text.match(/^(.*?)[\s,]+(?:ch(?:apter)?\.?\s*)?(\d+(?:\.\d+)?)\s*$/i);
  if (m && m[1].trim()) {
    title = m[1].trim();
    chapter = parseFloat(m[2]);
  }
  return out('resolve_chapter', { title, chapter });
}

return out('reply_only', { text: 'send a manga title (e.g. "one piece"). /help' });

const route = $('Route').first().json;
const chapter = $input.first().json;
const rels = chapter?.data?.relationships || [];
const mangaRel = rels.find(r => r.type === 'manga');
if (!mangaRel?.id) {
  return [{ json: { _error: true, chatId: route.chatId, text: '\u274C Could not resolve manga from chapter.' } }];
}
const attrs = chapter.data.attributes || {};
const chapterNum = parseFloat(attrs.chapter);
return [{ json: {
  chatId: route.chatId,
  chapterId: route.chapterId,
  mangaId: String(mangaRel.id).toLowerCase(),
  chapterNum: isNaN(chapterNum) ? null : chapterNum
}}];

const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};
const route = $('Route').first().json;
const r = $input.first().json;
const TTL_MS = 5 * 60 * 1000;
const title = r.title || route.title || r.mangaId;
const chapterNum = (r.chapterNum != null) ? r.chapterNum : null;
data.pending[route.chatId] = {
  step: 'awaiting_choice',
  chapterId: r.chapterId,
  mangaId: r.mangaId,
  title,
  chapterNum,
  expiresAt: Date.now() + TTL_MS
};
const text = [
  'resolved (manganow)',
  'title: ' + title,
  'chapter: ' + (chapterNum != null ? chapterNum : '?'),
  'mangaId: `' + r.mangaId + '`',
  'chapter url: ' + r.chapterId,
  '',
  'thumbnail: auto / skip'
].join('\n');
return [{ json: { chatId: route.chatId, text }}];

const data = $getWorkflowStaticData('global');
data.pending = data.pending || {};
const route = $('Route').first().json;
const upload = $input.first().json;
const TTL_MS = 5 * 60 * 1000;
const pending = data.pending[route.chatId];
if (!pending) {
  return [{ json: { chatId: route.chatId, _error: true, text: 'session expired during thumb generation' }}];
}
pending.thumbUrl = upload.url;
pending.step = 'awaiting_confirm';
pending.expiresAt = Date.now() + TTL_MS;
const caption = [
  'thumb uploaded (R2)',
  'thumbUrl: `' + upload.url + '`',
  'mangaId: `' + pending.mangaId + '` chapter: ' + (pending.chapterNum != null ? pending.chapterNum : '?'),
  '',
  'post / retry / cancel?'
].join('\n');
return [{ json: {
  chatId: route.chatId,
  thumbUrl: upload.url,
  caption
}}];

