  const parsed = JSON.parse(content);
  caption = (parsed.caption || '').toString().trim();
  imagePrompt = (parsed.image_prompt || parsed.imagePrompt || '').toString().trim();
} catch (e) {
  imagePrompt = String(content || '').trim();
}
if (!imagePrompt) imagePrompt = String(content || '').trim();

const data = $getWorkflowStaticData('global');
if (!Array.isArray(data.thumbHistory)) data.thumbHistory = [];
if (caption) {
  data.thumbHistory.push(caption);
  if (data.thumbHistory.length > 40) data.thumbHistory = data.thumbHistory.slice(-40);
}

return [{ json: { chatId: route.chatId, caption, image_prompt: imagePrompt, prompt: imagePrompt } }];

